// VisionWeaver Prime image assets, embedded as data URIs.
// These are the REAL photos from the VisionWeaver-Prime repo
// (assets-b64/*.jpg.b64), decoded to JPEG and embedded here because
// the repo's binary-file tools only accept UTF-8 text. No image was
// generated or altered; each entry is the original Prime asset.
// VWImage resolves a "/vw/<name>.jpg" src through this map.

export const VW_IMAGES: Record<string, string> = {
  "/vw/hero_director.jpg": "data:image/jpeg;base64,",
  "/vw/feature_avatar-engineering.jpg": "data:image/jpeg;base64,",
  "/vw/feature_worlds-locations.jpg": "data:image/jpeg;base64,",
  "/vw/feature_create-produce.jpg": "data:image/jpeg;base64,",
  "/vw/feature_design-commercial.jpg": "data:image/jpeg;base64,",
  "/vw/feature_media-library.jpg": "data:image/jpeg;base64,",
  "/vw/feature_post-production.jpg": "data:image/jpeg;base64,",
  "/vw/feature_distribution-growth.jpg": "data:image/jpeg;base64,",
  "/vw/feature_quality-audit.jpg": "data:image/jpeg;base64,",
  "/vw/feature_teams.jpg": "data:image/jpeg;base64,",
  "/vw/feature_finance-accounting.jpg": "data:image/jpeg;base64,",
  "/vw/feature_it-security.jpg": "data:image/jpeg;base64,",
  "/vw/feature_resources.jpg": "data:image/jpeg;base64,",
};

export function resolveVWImage(src: string): string {
  return VW_IMAGES[src] ?? src;
}
